// Usage: node make-wav.mjs out.wav "sentence" [pauseMs] ["sentence" ...] — TTS each sentence, join with pauses, write 24 kHz mono WAV.
import { writeFileSync } from "node:fs";
const [out, ...parts] = process.argv.slice(2); const KEY = process.env.OPENAI_API_KEY; const chunks = [Buffer.alloc(48000)];
for (const part of parts) {
  if (/^\d+$/.test(part)) { chunks.push(Buffer.alloc(48 * Number(part))); continue; }
  const r = await fetch("https://api.openai.com/v1/audio/speech", { method: "POST", headers: { Authorization: `Bearer ${KEY}`, "Content-Type": "application/json" }, body: JSON.stringify({ model: "gpt-4o-mini-tts", voice: "alloy", input: part, response_format: "pcm" }) });
  if (!r.ok) throw new Error(await r.text()); chunks.push(Buffer.from(await r.arrayBuffer()));
}
chunks.push(Buffer.alloc(48 * 6000)); const pcm = Buffer.concat(chunks); const h = Buffer.alloc(44);
h.write("RIFF", 0); h.writeUInt32LE(36 + pcm.length, 4); h.write("WAVEfmt ", 8); h.writeUInt32LE(16, 16); h.writeUInt16LE(1, 20); h.writeUInt16LE(1, 22); h.writeUInt32LE(24000, 24); h.writeUInt32LE(48000, 28); h.writeUInt16LE(2, 32); h.writeUInt16LE(16, 34); h.write("data", 36); h.writeUInt32LE(pcm.length, 40);
writeFileSync(out, Buffer.concat([h, pcm])); console.log(out, (pcm.length / 48000).toFixed(1) + "s");
EOF
